pre-actions.script:
// the form's choice (from, to) goes to the comparison's own address, before anything renders
const chosen=ec.resource.script('component://mr-pass/screen/Smithy/Smithy.js').compareRedirect(passBases.smithy,String(namePath || ''))
if(chosen){ec.resource.script('component://mr-pass/screen/Smithy/Smithy.js').redirectBefore(sri,chosen);return}

actions.script:
const smithy=ec.resource.script('component://mr-pass/screen/Smithy/Smithy.js')
smithyRepository=smithy.repositoryShell(resolvedSiteId,String(repositoryId || ''),passBases.smithy,String(publicPath || ''))
// base and head are the resolver's (the path); the form's fields are from and to (the pre-actions)
view=smithy.compare(smithyRepository,String(base || ''),String(head || ''),String(headRepositoryPath || ''))
changes=view.result
